new=pd.DataFrame(rows)
# prevent duplicate IDs if script rerun
new=new[~new['id'].isin(df['id'])]
# add structured fields for all rows
all_df=pd.concat([df,new],ignore_index=True)

def derive_category(cat):
    s=str(cat).lower()
    if 'negoti' in s or 'diplom' in s: return 'Negotiation/Diplomacy'
    if 'conflict' in s: return 'Conflict Resolution'
    if 'leadership' in s or 'governance' in s: return 'Leadership/Governance'
    if 'risk' in s: return 'Risk Management'
    if 'uncertainty' in s: return 'Uncertainty/Decision Making'
    if 'ethic' in s: return 'Ethics/Decision Making'
    if 'alliance' in s: return 'Alliance/Cooperation'
    if 'crisis' in s: return 'Crisis Management'
    if 'communication' in s: return 'Communication'
    if 'strategy' in s: return 'Strategy'
    return str(cat)

all_df['strategic_dimension']=all_df['problem_category'].map(derive_category)
all_df['retrieval_text']=all_df.apply(lambda r: f"Problem: {r.get('contemporary_problem','')}. Challenge: {r.get('strategic_challenge','')}. Objective: {r.get('strategic_insight','')}. Category: {r.get('strategic_dimension','')}. Historical situation: {r.get('situation_description','')}",axis=1)
all_df.to_csv(p,index=False)
print('Saved',len(all_df),'records; added',len(new))
